  getGetDashboardQueryKey, getGetWasteRecordQueryKey, getListActivityQueryKey,
  getListWasteRecordsQueryKey, useChangeWasteStatus, useCreateWasteRecord,
  useGetDashboard, useGetWasteRecord, useListActivity, useListWasteRecords,
